import re, sys, json
sys.stdout.reconfigure(encoding='utf-8')
p = 'public/index.html'
h = open(p, encoding='utf8').read()

def rep(old, new):
    global h
    assert old in h, old[:80]
    h = h.replace(old, new, 1)

# ---------- compact tiles (icon + title on one row, description below): six rows fit on a normal screen
rep(".home{display:grid;grid-template-columns:repeat(3,1fr);grid-auto-rows:1fr;gap:18px}", ".home{display:grid;grid-template-columns:repeat(3,1fr);grid-auto-rows:1fr;gap:12px}")
a = h.index(".tile{display:flex;flex-direction:column;padding:18px 20px;min-height:160px;")
b = h.index("\n.tile .ic", a)
h = h[:a] + ".tile{display:grid;grid-template-columns:auto 1fr;column-gap:10px;align-content:center;padding:10px 16px;min-height:96px;text-decoration:none;color:var(--ink)}" + h[b:]
a = h.index(".tile .ic{"); b = h.index("\n", h.index(".tile span{", a))
h = h[:a] + """.tile .ic{grid-column:1;font-size:1.5rem;line-height:1.2;margin:0}
.tile b{grid-column:2;display:block;font-size:1.12rem;line-height:1.3;align-self:center}
.tile span{grid-column:1/-1;display:block;color:var(--muted);font-size:.8rem;line-height:1.45;margin-top:3px;padding-top:0}""" + h[b:]

# ---------- the new tile, between "about" and "jannah"
rep('<a class="tile" href="#jannah">', '<a class="tile" href="#names"><div class="ic">✨</div><b>أسماء الله الحسنى في القرآن</b><span>الأسماء الواردة في الآيات بلفظها، ومعنى كل اسم وموضعه</span></a>\n    <a class="tile" href="#jannah">')

